use std::sync::{Arc, Mutex};
use std::thread;

struct Counter {
    c: i32,
}

fn w1(m: Arc<Mutex<Counter>>) {
    let mut guard = m.lock().unwrap();
    let current = guard.c;
    guard.c = current + 1;
}

fn w2(m: Arc<Mutex<Counter>>) {
    let mut guard = m.lock().unwrap();
    let current = guard.c;
    guard.c = current + 1;
}

fn main() {
    let m = Arc::new(Mutex::new(Counter { c: 0 }));

    let m1 = Arc::clone(&m);
    let h1 = thread::spawn(move || w1(m1));

    let m2 = Arc::clone(&m);
    let h2 = thread::spawn(move || w2(m2));

    h1.join().unwrap();
    h2.join().unwrap();

    println!("DONE done=1");
}
